// ---------- 时空错乱素材：Codex 原图打包成图集（原版是 5 千万字节的 base64 脚本）----------
(function () {
  let meta = null, metaP = null; const pages = [], cut = {};
  const load = src => new Promise((ok, no) => { const im = new Image(); im.onload = () => ok(im); im.onerror = () => no(new Error('素材加载失败：' + src)); im.src = src; });
  const M = () => metaP || (metaP = fetch('skx_assets/meta.json').then(r => r.json()).then(m => (meta = m)));
  const page = i => pages[i] || (pages[i] = load('skx_assets/p' + i + '.webp'));
  window.SKX_IMG = async file => {
    await M(); const k = meta.files[file]; if (!k) throw new Error('素材缺失：' + file);
    if (cut[k]) return cut[k];
    const [p, x, y, w, h] = meta.atlas[k], [ox, oy, fw, fh] = meta.off[k], im = await page(p);
    const c = document.createElement('canvas'); c.width = fw; c.height = fh; c.getContext('2d').drawImage(im, x, y, w, h, ox, oy, w, h);   // 还原成原尺寸（透明边离线裁掉了）
    return (cut[k] = c);
  };
})();

