// Review composition only: 1500ms eyes, followed by a static dragon design reveal.
function reviewSmooth(v){v=Math.max(0,Math.min(1,v));return v*v*(3-2*v)}
function reviewHalo(c,x,y,rx,ry,col,a,blend='screen'){if(a<=0)return;c.save();c.translate(x,y);c.scale(1,ry/rx);c.globalAlpha=a;c.globalCompositeOperation=blend;const g=c.createRadialGradient(0,0,1,0,0,rx);g.addColorStop(0,col+'bd');g.addColorStop(.42,col+'45');g.addColorStop(1,col+'00');c.fillStyle=g;c.fillRect(-rx,-rx,rx*2,rx*2);c.restore()}
function drawEye1500(c,im,t){if(t<0||t>=1500)return;const fade=reviewSmooth(t/180)*(1-reviewSmooth((t-1160)/340)),scale=.97+.04*reviewSmooth(t/1500),w=540*scale,h=w*295/900,x=650-w/2,y=120-h/2;
 c.save();c.globalAlpha=fade;c.drawImage(im,x,y,w,h);c.restore();
 const pulse=.5+.5*Math.sin((t-200)/760*Math.PI*2),gx=x+w*.306,bx=x+w*.693,yy=y+h*.525;
 reviewHalo(c,bx,yy,20*scale,15*scale,'#08030e',fade*(.22+.7*pulse),'source-over');
 reviewHalo(c,gx,yy,21*scale,15*scale,'#e0a13b',fade*(.16+.77*pulse));
 reviewHalo(c,bx,yy,24*scale,17*scale,'#66327f',fade*(.12+.38*(1-pulse)));
 c.save();c.globalAlpha=fade*(.3+.7*pulse);c.globalCompositeOperation='screen';c.fillStyle='#ffe2a5';c.beginPath();c.ellipse(gx+3*Math.sin(t*.006),yy-4,1.8,1.2,0,0,Math.PI*2);c.fill();c.restore();
}
function drawDragonReview(c,assets,t,mode='sequence',night=true){c.clearRect(0,0,960,540);const bg=assets.bg,sc=Math.max(1008/bg.width,588/bg.height);c.drawImage(bg,(960-bg.width*sc)/2,(540-bg.height*sc)/2,bg.width*sc,bg.height*sc);c.fillStyle=night?'#100a2394':'#1920364a';c.fillRect(0,0,960,540);
 const reveal=mode==='static'?1:mode==='eyes'?0:reviewSmooth((t-1350)/650);
 if(reveal>0){reviewHalo(c,650,200,230,240,'#542375',reveal*.24);c.save();c.globalAlpha=reveal;const h=470,w=h*assets.dragon.width/assets.dragon.height;c.drawImage(assets.dragon,650-w/2,8+(1-reveal)*18,w,h);c.restore();}
 for(const[x,y]of [[158,400],[297,446],[438,399]]){const im=assets.dummy,h=190;c.drawImage(im,x-h*im.width/im.height/2,y-h,h*im.width/im.height,h)}
 const im=assets.hero,h=230;c.drawImage(im,780-h*im.width/im.height/2,450-h,h*im.width/im.height,h);
 if(mode!=='static')drawEye1500(c,assets.eyes,t);
 c.fillStyle='#07111fee';c.fillRect(0,495,960,45);c.fillStyle='#dec6e8';c.font='18px GameCJK,serif';c.fillText('洛尘 · 紫黑龙形 / 双瞳流光',24,522);c.textAlign='right';c.font='11px GameCJK,system-ui';c.fillStyle='#bac2d5';c.fillText(mode==='eyes'?'眼神动画 · 1500ms':'造型与衔接预览 · 龙形尚为静态关键帧',934,522);c.textAlign='left';
}

const VFXFILM={duration:11200,samples:672,eyeEnd:1000,cycleEnd:5000,chargeEnd:6000,hitTime:6180,breathEnd:7300,dissolveStart:9100,dragonEnd:9750,partyReturn:9850,healTime:10400};
const INTRO=1500;const FILM={duration:9300,samples:558,eyeEnd:1000,transformEnd:1800,cycleEnd:3800,chargeEnd:5300,hitTime:5480,breathEnd:6300,dissolveStart:8000,dragonEnd:8600,partyReturn:8600,healTime:8800};
function visualTime(t){const knots=[[0,1500],[300,1800],[2300,4000],[2850,5000],[3800,6000],[4800,7300],[6500,9100],[7100,9750],[7150,9850],[7300,10400],[7800,11200]];for(let i=1;i<knots.length;i++){const a=knots[i-1],b=knots[i];if(t<=b[0])return mix(a[1],b[1],clamp((t-a[0])/(b[0]-a[0])));}return 11200;}
function actualTime(t){const knots=[[0,1500],[300,1800],[2300,4000],[2850,5000],[3800,6000],[4800,7300],[6500,9100],[7100,9750],[7150,9850],[7300,10400],[7800,11200]];for(let i=1;i<knots.length;i++){const a=knots[i-1],b=knots[i];if(t<=b[1])return mix(a[0],b[0],clamp((t-a[1])/(b[1]-a[1])));}return 7800;}

const clamp=v=>Math.max(0,Math.min(1,v)),ease=v=>{v=clamp(v);return v*v*(3-2*v)},mix=(a,b,v)=>a+(b-a)*v;
// V9 adds time only to becoming the dragon. All approved V8 drawing and battle
// events continue to use their original story clock after 1800 story ms.
const CLOCK_KNOTS=Object.freeze([[0,0],[700,700],[1600,1200],[2250,1500],[2800,1800],[10300,9300]].map(p=>Object.freeze(p)));
function mapClock(ms,reverse=false){const a=reverse?1:0,b=1-a,v=Math.max(0,Number(ms)||0);for(let i=1;i<CLOCK_KNOTS.length;i++){const left=CLOCK_KNOTS[i-1],right=CLOCK_KNOTS[i];if(v<=right[a])return mix(left[b],right[b],clamp((v-left[a])/(right[a]-left[a])));}return CLOCK_KNOTS[CLOCK_KNOTS.length-1][b];}
function toStory(elapsed){return mapClock(elapsed);}
function toElapsed(story){return mapClock(story,true);}
const REAL_FILM=Object.freeze(Object.fromEntries(Object.entries(FILM).map(([key,value])=>[key,key==='samples'?618:toElapsed(value)])));
function phaseName(t){return t<1000?'① 双瞳施法':t<3000?'② 昼夜轮转 · 第一轮':t<5000?'③ 昼夜轮转 · 第二轮':t<6000?'④ 紫月独悬 · 仰头蓄力':t<7300?'⑤ 至暗月夜 · 紫雷龙息':t<9100?'⑥ 日出 · 白光凝龙':t<10400?'⑦ 金色光雨 · 飞向我方':'⑧ 光雨落身 · 回血解控'}
function dragonIndex(t){return Math.max(0,Math.min(60,Math.floor((t-1000)*.012+1e-7)))}
function sprite(c,im,x,y,w,h,alpha=1,rot=0){if(alpha<=0)return;c.save();c.globalAlpha*=clamp(alpha);c.translate(x,y);c.rotate(rot);c.drawImage(im,-w/2,-h/2,w,h);c.restore()}
function halo(c,x,y,rx,ry,col,alpha){reviewHalo(c,x,y,rx,ry,col,alpha)}
function cover(c,im){const scale=Math.max(984/im.width,564/im.height);c.drawImage(im,(960-im.width*scale)/2,(540-im.height*scale)/2,im.width*scale,im.height*scale)}
function dayAmount(t){const rt=actualTime(t);if(rt<2300){const q=(rt%1150)/1150;return ease((q-.08)/.14)*(1-ease((q-.49)/.16));}if(rt<4800)return 0;return ease((rt-4800)/300);}
function ambient(c,t){if(t<1000)return;const d=dayAmount(t),weight=1-ease((t-10950)/250);c.save();c.globalCompositeOperation='multiply';c.fillStyle=`rgba(1,2,9,${((1-d)*.995+.015*d)*weight})`;c.fillRect(-20,-20,1000,580);c.globalCompositeOperation='screen';c.fillStyle=`rgba(255,222,153,${d*.36*weight})`;c.fillRect(-20,-20,1000,580);const g=c.createLinearGradient(0,0,0,540);g.addColorStop(0,`rgba(255,237,177,${d*.16*weight})`);g.addColorStop(1,'rgba(255,194,100,0)');c.fillStyle=g;c.fillRect(0,0,960,540);c.restore();}
function celestialState(t){const d=dayAmount(t),day=d>.5;return{sun:day?ease((d-.5)*2):0,moon:day?0:ease((.5-d)*2)};}
