 return{elapsed,phase,morph,day:1-morph,nightAge:clamp((elapsed-OPENING_SKY.nightChargeStart)/(OPENING_SKY.nightChargeEnd-OPENING_SKY.nightChargeStart)),center:{x:OPENING_SKY.x,y:OPENING_SKY.y},active:story<INTRO};
